create table cook_session (
  id uuid not null default gen_random_uuid(),
  user_id uuid,
  meal1_id text not null,
  meal2_id text not null,
  current_step integer not null default 0,
  total_steps integer not null default 0,
  week_number integer not null default 1,
  completed boolean not null default false,
  updated_at timestamp with time zone default now()
);
create table grocery_state (
  id uuid not null default gen_random_uuid(),
  user_id uuid,
  checked_items jsonb not null default '{}'::jsonb,
  servings jsonb not null default '{}'::jsonb,
  updated_at timestamp with time zone default now()
);
create table notes (
  id uuid not null default uuid_generate_v4(),
  user_id uuid not null,
  item_id text not null,
  description text,
  notes text,
  updated_at timestamp with time zone default now()
);
create table progress (
  id uuid not null default uuid_generate_v4(),
  user_id uuid not null,
  item_id text not null,
  level integer not null default 0,
  updated_at timestamp with time zone default now(),
  last_quizzed timestamp with time zone,
  streak integer not null default 0
);
create table recipe_preferences (
  id uuid not null default gen_random_uuid(),
  user_id uuid,
  recipe_id text not null,
  auto_pairing_eligible boolean,
  rating integer,
  favourite boolean not null default false,
  notes text,
  updated_at timestamp with time zone default now()
);
create table schedule (
  id uuid not null default gen_random_uuid(),
  user_id uuid,
  cook_day integer not null default 6,
  current_week integer not null default 1,
  last_cooked_at timestamp with time zone,
  updated_at timestamp with time zone default now()
);
create table synonyms (
  id uuid not null default uuid_generate_v4(),
  user_id uuid not null,
  item_id text not null,
  synonym text not null,
  created_at timestamp with time zone default now()
);
create table user_pairings (
  id uuid not null default gen_random_uuid(),
  user_id uuid,
  week_number integer not null,
  meal_a_id text not null,
  meal_b_id text not null,
  created_at timestamp with time zone default now()
);
create table user_settings (
  user_id uuid not null,
  streak integer default 0,
  last_study_date date,
  updated_at timestamp with time zone default now(),
  unlocked_levels jsonb default '[1]'::jsonb,
  configuration jsonb default '{}'::jsonb
);
create table write_progress (
  user_id uuid not null,
  item_id text not null,
  level integer not null default 0,
  last_quizzed timestamp with time zone,
  updated_at timestamp with time zone not null default now(),
  streak integer not null default 0
);

