CREATE OR REPLACE FUNCTION public.force_read_level(p_item_id text, p_level integer)
 RETURNS integer
 LANGUAGE plpgsql
AS $function$
BEGIN
    INSERT INTO progress (user_id, item_id, level, streak, updated_at)
    VALUES (auth.uid(), p_item_id, p_level, 0, now())
    ON CONFLICT (user_id, item_id)
    DO UPDATE SET level = p_level, streak = 0, updated_at = now();
    RETURN p_level;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.force_write_level(p_item_id text, p_level integer, p_user_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
AS $function$
BEGIN
    INSERT INTO write_progress (user_id, item_id, level, streak, updated_at)
    VALUES (p_user_id, p_item_id, p_level, 0, now())
    ON CONFLICT (user_id, item_id)
    DO UPDATE SET level = EXCLUDED.level, streak = 0, updated_at = now();
    RETURN p_level;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.rls_auto_enable()
 RETURNS event_trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.upsert_note(p_item_id text, p_description text, p_notes text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
begin
  insert into notes (user_id, item_id, description, notes, updated_at)
  values (auth.uid(), p_item_id, p_description, p_notes, now())
  on conflict (user_id, item_id)
  do update set description = p_description, notes = p_notes, updated_at = now();
end;
$function$
;

CREATE OR REPLACE FUNCTION public.upsert_progress(p_item_id text, p_level integer, p_threshold integer DEFAULT 0)
 RETURNS integer
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_threshold int := COALESCE(p_threshold, 0);
    v_current   int;
    v_streak    int;
    v_level     int;
    v_new_streak int;
BEGIN
    SELECT level, streak INTO v_current, v_streak
    FROM progress
    WHERE user_id = auth.uid() AND item_id = p_item_id;

    IF v_current IS NULL THEN
        v_current := 0;
        v_streak  := 0;
    END IF;

    IF v_threshold >= 2 AND p_level > v_current THEN
        v_new_streak := v_streak + 1;
        IF v_new_streak >= v_threshold THEN
            v_level := p_level;
            v_new_streak := 0;
        ELSE
            v_level := v_current;
        END IF;
    ELSIF p_level = v_current THEN
        v_level := p_level;
        v_new_streak := v_streak + 1;
    ELSE
        v_level := p_level;
        v_new_streak := 0;
    END IF;

    INSERT INTO progress (user_id, item_id, level, streak, updated_at)
    VALUES (auth.uid(), p_item_id, v_level, v_new_streak, now())
    ON CONFLICT (user_id, item_id)
    DO UPDATE SET
        level      = v_level,
        streak     = v_new_streak,
        updated_at = now();

    RETURN v_level;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.upsert_user_settings(p_streak integer, p_last_study_date date, p_unlocked_levels jsonb DEFAULT NULL::jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
declare
  existing_levels jsonb;
  merged_levels jsonb;
begin
  select coalesce(unlocked_levels, '[]'::jsonb) into existing_levels
  from user_settings
  where user_id = auth.uid();

  existing_levels := coalesce(existing_levels, '[]'::jsonb);

  if p_unlocked_levels is null or p_unlocked_levels = '[]'::jsonb then
    merged_levels := case
      when existing_levels = '[]'::jsonb then '[1]'::jsonb
      else existing_levels
    end;
  elsif existing_levels = '[]'::jsonb then
    merged_levels := p_unlocked_levels;
  elsif jsonb_array_length(p_unlocked_levels) >= jsonb_array_length(existing_levels) then
    merged_levels := p_unlocked_levels;
  else
    merged_levels := existing_levels;
  end if;

  insert into user_settings (user_id, streak, last_study_date, unlocked_levels, updated_at)
  values (auth.uid(), p_streak, p_last_study_date, merged_levels, now())
  on conflict (user_id)
  do update set
    streak = p_streak,
    last_study_date = p_last_study_date,
    unlocked_levels = merged_levels,
    updated_at = now();
end;
$function$
;

-- NOTE: two overloads of upsert_user_settings exist. The page calls this 4-arg one
-- (p_streak, p_last_study_date, p_configuration), relying on p_unlocked_levels
-- defaulting to NULL. Its indentation is mangled in the live database; reproduced here
-- as-is rather than tidied, so this file matches what is actually deployed.
CREATE OR REPLACE FUNCTION public.upsert_user_settings(p_streak integer, p_last_study_date date, p_unlocked_levels jsonb DEFAULT NULL::jsonb, p_configuration jsonb DEFAULT NULL::jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
        declare
          existing_levels jsonb;
            merged_levels jsonb;
            begin
              select coalesce(unlocked_levels, '[]'::jsonb) into existing_levels
                from user_settings
                  where user_id = auth.uid();

                    existing_levels := coalesce(existing_levels, '[]'::jsonb);

                      if p_unlocked_levels is null or p_unlocked_levels = '[]'::jsonb then
                          merged_levels := case
                                when existing_levels = '[]'::jsonb then '[1]'::jsonb
                                      else existing_levels
                                          end;
                                            elsif existing_levels = '[]'::jsonb then
                                                merged_levels := p_unlocked_levels;
                                                  elsif jsonb_array_length(p_unlocked_levels) >= jsonb_array_length(existing_levels) then
                                                      merged_levels := p_unlocked_levels;
                                                        else
                                                            merged_levels := existing_levels;
                                                              end if;

                                                                insert into user_settings (user_id, streak, last_study_date, unlocked_levels, configuration, updated_at)
                                                                  values (auth.uid(), p_streak, p_last_study_date, merged_levels,
                                                                      coalesce(p_configuration, '{}'::jsonb),
                                                                          now())
                                                                            on conflict (user_id) do update set
                                                                                streak = p_streak,
                                                                                    last_study_date = p_last_study_date,
                                                                                        unlocked_levels = merged_levels,
                                                                                            configuration = coalesce(p_configuration, user_settings.configuration),
                                                                                                updated_at = now();
                                                                                                end;
                                                                                                $function$
;

CREATE OR REPLACE FUNCTION public.upsert_write_progress(p_item_id text, p_level integer, p_last_quizzed timestamp with time zone, p_user_id uuid, p_threshold integer DEFAULT 0)
 RETURNS integer
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_threshold int := COALESCE(p_threshold, 0);
    v_current   int;
    v_streak    int;
    v_level     int;   -- level we will actually commit
    v_new_streak int;
BEGIN
    SELECT level, streak INTO v_current, v_streak
    FROM write_progress
    WHERE user_id = p_user_id AND item_id = p_item_id;

    IF v_current IS NULL THEN
        v_current := 0;
        v_streak  := 0;
    END IF;

    IF v_threshold >= 2 AND p_level > v_current THEN
        -- Gated rung: hold here and count up, release only at threshold.
        v_new_streak := v_streak + 1;
        IF v_new_streak >= v_threshold THEN
            v_level := p_level;      -- promote (rung change)
            v_new_streak := 0;       -- rung changed -> reset
        ELSE
            v_level := v_current;    -- stay put (same rung -> streak stands)
        END IF;
    ELSIF p_level = v_current THEN
        -- Same rung, not gated: generic increment.
        v_level := p_level;
        v_new_streak := v_streak + 1;
    ELSE
        -- Any other rung change (promotion elsewhere, or a lapse/drop): reset.
        v_level := p_level;
        v_new_streak := 0;
    END IF;

    INSERT INTO write_progress (user_id, item_id, level, last_quizzed, streak, updated_at)
    VALUES (p_user_id, p_item_id, v_level, p_last_quizzed, v_new_streak, now())
    ON CONFLICT (user_id, item_id)
    DO UPDATE SET
        level        = EXCLUDED.level,
        last_quizzed = EXCLUDED.last_quizzed,
        streak       = EXCLUDED.streak,
        updated_at   = now();

    RETURN v_level;
END;
$function$
;

